package com.huawei.oss.wireless.experienceassuranceservice.common.impl.utils;

import com.huawei.bsp.log.OssLog;
import com.huawei.bsp.log.OssLogFactory;
import com.huawei.bsp.remoteservice.exception.ServiceException;
import com.huawei.maos.commons.deploy.EnvUtil;
import com.huawei.maos.commons.text.StringUtil;
import com.huawei.oss.rest.util.RestCaller;
import com.huawei.oss.rest.util.RestMethod;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.Map;
import java.util.Optional;
import java.util.stream.Collectors;

/**
 * Utility class for querying instance IDs of ExperienceAssuranceService.
 * Provides methods to query all instance IDs and the current instance ID.
 */
public class InstanceUtils {

    private static final String INSTANCE_ONLY_POLICY = "instanceOnly";

    private static final String BACKEND_LIST_POLICY_HEADER = "XX-Backend-List-Policy";

    private static final String BACKEND_LIST_HEADER = "Xx-Backend-List";

    private static final String ALL_INSTANCES_PREFIX = "all=";

    private static final String POD_NAME_ENV = "POD_NAME";

    private static final String INSTANCE_ID_SEPARATOR = ",";

    private static final String INSTANCE_NAME_SEPARATOR = "-";

    private static final String POLICY_URL = "/rest/oss/inner/experienceassurance/v1/policy";

    private static final OssLog LOGGER = OssLogFactory.getLogger(InstanceUtils.class);

    /**
     * Query all instance IDs of the ExperienceAssuranceService by calling the IR policy endpoint.
     *
     * @return list of all instance IDs as integers
     */
    public static List<Integer> queryAllInstanceIds() {
        List<Integer> instanceIds = new ArrayList<>();
        try {
            LOGGER.info("Start to query all instance IDs");
            Map<String, String> respHeaderMap = new RestCaller.Builder(POLICY_URL, RestMethod.POST)
                .header(BACKEND_LIST_POLICY_HEADER, INSTANCE_ONLY_POLICY)
                .build()
                .call()
                .getRespHeaderMap();

            String backendList = getBackendList(respHeaderMap);
            if (StringUtil.notEmpty(backendList) && backendList.startsWith(ALL_INSTANCES_PREFIX)) {
                String instances = backendList.substring(ALL_INSTANCES_PREFIX.length());
                instanceIds = Arrays.stream(instances.split(INSTANCE_ID_SEPARATOR))
                    .map(InstanceUtils::parseInstanceId)
                    .filter(Optional::isPresent)
                    .map(Optional::get)
                    .collect(Collectors.toList());
            }
            LOGGER.info("Successfully queried all instance IDs, instance count: " + instanceIds.size());
        } catch (ServiceException e) {
            LOGGER.error("ServiceException occurred while querying all instance IDs", e);
        } catch (Exception e) {
            LOGGER.error("Exception occurred while querying all instance IDs", e);
        }
        return instanceIds;
    }

    /**
     * Get the backend list value from the response header map using case-insensitive key matching.
     *
     * @param respHeaderMap response header map from the IR policy endpoint
     * @return the backend list value, or empty string if not found
     */
    private static String getBackendList(Map<String, String> respHeaderMap) {
        if (respHeaderMap == null) {
            return "";
        }
        for (Map.Entry<String, String> entry : respHeaderMap.entrySet()) {
            if (entry.getKey() != null && entry.getKey().equalsIgnoreCase(BACKEND_LIST_HEADER)) {
                return entry.getValue();
            }
        }
        return "";
    }

    /**
     * Query the current instance ID from the POD_NAME environment variable.
     *
     * @return the current instance ID as an Optional integer
     */
    public static Optional<Integer> queryCurrentInstanceId() {
        try {
            String podName = EnvUtil.getEnv(POD_NAME_ENV);
            LOGGER.info("Start to query current instance ID, podName: " + podName);
            if (StringUtil.isEmpty(podName)) {
                LOGGER.warn("POD_NAME environment variable is empty");
                return Optional.empty();
            }
            Optional<Integer> instanceId = parseInstanceId(podName);
            instanceId.ifPresent(id -> LOGGER.info("Successfully queried current instance ID: " + id));
            return instanceId;
        } catch (Exception e) {
            LOGGER.error("Exception occurred while querying current instance ID", e);
            return Optional.empty();
        }
    }

    /**
     * Parse the instance ID from an instance name string.
     * The instance name is expected to be in the format "service-b-1",
     * where the last segment after "-" is the numeric instance ID.
     *
     * @param instanceName the instance name string (e.g., "service-b-1")
     * @return the parsed instance ID as an Optional integer
     */
    private static Optional<Integer> parseInstanceId(String instanceName) {
        if (StringUtil.isEmpty(instanceName)) {
            return Optional.empty();
        }
        try {
            String[] parts = instanceName.split(INSTANCE_NAME_SEPARATOR);
            int id = Integer.parseInt(parts[parts.length - 1]);
            return Optional.of(id);
        } catch (NumberFormatException e) {
            LOGGER.error("Failed to parse instance ID from instanceName: " + instanceName, e);
            return Optional.empty();
        }
    }
}
